'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const seedBrief={name:'College fest merchandise',project:'TechSpace Fest 2026',category:'Printed merchandise',description:'100 premium T-shirts for the college fest organising team. Two-colour front print and a small back logo.',quantity:100,location:'Dwarka, New Delhi',min:30000,max:35000,date:'2026-11-10',must:'180 GSM cotton; accurate sizing; delivery by 10 November',addons:'Printed sample before production; individual packaging',flex:'Packaging style can change. Advance payment up to 40%.',priority:'Balanced: quality, cost and delivery'};
const sampleOffers=[{id:'studio',name:'Studio Merch',initial:'S',colour:'purple',total:32400,date:'8 Nov',advance:'30%',material:'180 GSM cotton',sample:'Included',pack:'Individual',contact:'Aarav',email:'aarav@studio-merch.example',file:'studio-merch-quotation.pdf',rank:1,label:'Best overall fit',compliance:'Meets all essentials',note:'A printed sample is included. All mandatory requirements are met. Ask for a better price while keeping the full scope.',draft:'Thank you for your quotation for 100 printed T-shirts. Your offer meets our material and delivery requirements, and we appreciate the included printed sample.\n\nCould you offer a revised total closer to ₹31,000, retaining the 180 GSM cotton, two-colour print, individual packaging, included sample, 8 November delivery, and 30% advance?\n\nPlease share your best written offer with all taxes and delivery included.'},
{id:'print',name:'Print & Co.',initial:'P',colour:'peach',total:30200,date:'9 Nov',advance:'40%',material:'180 GSM cotton',sample:'₹800 optional',pack:'Bulk',contact:'Isha',email:'isha@print-co.example',file:'print-and-co-offer.pdf',rank:2,label:'Best complete base price',compliance:'Meets all essentials',note:'Mandatory conditions are met. A printed sample is an optional ₹800 add-on; bulk packaging is within the allowed compromise.',draft:'Thank you for your quotation of ₹30,200, inclusive of taxes and delivery. Your material and 9 November delivery meet our requirements.\n\nCould you include the printed sample in this total, instead of the separate ₹800 charge? Bulk packaging is acceptable. Please retain the 40% advance and all other quoted specifications.\n\nPlease send a revised written quotation confirming the complete total.'},
{id:'thread',name:'Threadworks',initial:'T',colour:'blue',total:34500,date:'6 Nov',advance:'25%',material:'200 GSM cotton',sample:'Included',pack:'Individual',contact:'Rohan',email:'rohan@threadworks.example',file:'threadworks-fest-quote.pdf',rank:3,label:'Earliest delivery',compliance:'Meets all essentials',note:'The 200 GSM fabric exceeds the 180 GSM minimum. Earliest delivery, with a higher price that remains inside the budget.',draft:'Thank you for your quotation. The 6 November delivery, included sample, and 25% advance are helpful.\n\nCould you reduce the ₹34,500 total toward ₹32,000 while retaining the quoted 200 GSM cotton, printing, packaging, and delivery date?\n\nPlease confirm your best all-inclusive price in a revised written quotation.'},
{id:'campus',name:'Campus Supply',initial:'C',colour:'mint',total:28800,date:'12 Nov',advance:'35%',material:'180 GSM cotton',sample:'Included',pack:'Bulk',contact:'Neha',email:'neha@campus-supply.example',file:'campus-supply-offer.pdf',rank:4,label:'Potential outside shortlist',compliance:'Delivery fails',note:'₹3,600 below Studio Merch, but delivery is two days after the mandatory deadline. Worth reconsidering only if delivery changes.',draft:'Thank you for your quotation of ₹28,800, inclusive of taxes and delivery. The material and payment terms fit our brief.\n\nYour proposed delivery date of 12 November is later than our mandatory 10 November deadline. Can you commit to delivery in Dwarka by 10 November, retaining the quoted total and other terms?\n\nPlease provide a revised written offer. We can reconsider the quotation if the delivery requirement is met.'},
{id:'quick',name:'QuickPrint',initial:'Q',colour:'pink',total:27000,date:'11 Nov',advance:'100%',material:'160 GSM blend',sample:'Not stated',pack:'Bulk',contact:'Dev',email:'dev@quickprint.example',file:'quickprint-estimate.pdf',rank:5,label:'Not applicable',compliance:'3 conditions fail',note:'Material, delivery and advance terms do not match the brief.',draft:''}];
const STORE='quotelens-workspaces-v3';
let saved={};try{saved=JSON.parse(localStorage.getItem(STORE)||'{}')}catch{}
let tenders=Array.isArray(saved.tenders)&&saved.tenders.length?saved.tenders:[];
if(!tenders.length){let previous={};try{previous=JSON.parse(localStorage.getItem('quotelens-design-v2')||'{}')}catch{}tenders=[{id:'fest-2026',brief:{...seedBrief},custom:[],drafts:{},newTender:false,createdAt:'2026-10-25'}];if(previous.brief){const old={id:previous.newTender?'imported-tender':'fest-2026',brief:{...seedBrief,...previous.brief},custom:previous.custom||[],drafts:previous.drafts||{},newTender:!!previous.newTender,createdAt:'2026-10-25'};if(previous.newTender)tenders.push(old);else tenders[0]=old;}}
let activeId=saved.activeId||tenders[0].id;
let state=tenders.find(t=>t.id===activeId)||tenders[0];activeId=state.id;
let view=new URLSearchParams(location.search).get('view')||'tenders';let selectedDraft='studio';let lastFocus=null;let toastTimer;
const validViews=['tenders','requirements','quotations','comparison','drafts','evaluation'];if(!validViews.includes(view))view='tenders';
const requestedId=new URLSearchParams(location.search).get('tender');if(requestedId&&tenders.some(t=>t.id===requestedId)){activeId=requestedId;state=tenders.find(t=>t.id===activeId);}
function persist(){try{localStorage.setItem(STORE,JSON.stringify({tenders,activeId}));return true}catch{toast('Browser storage is unavailable. Changes will last for this session.');return false}}
function activateTender(id){const t=tenders.find(t=>t.id===id);if(!t)return false;activeId=id;state=t;selectedDraft='studio';persist();return true;}
function createTender(name,project){const t={id:crypto.randomUUID(),brief:{...seedBrief,name,project,description:'',must:'',addons:'',flex:'',location:'',min:0,max:0,quantity:1,date:''},custom:[],drafts:{},newTender:true,createdAt:new Date().toISOString().slice(0,10)};t.activity=[{at:new Date().toISOString(),level:'INFO',event:'tender.created',message:'Created an independent tender workspace.'}];tenders.push(t);activateTender(t.id);return t;}
function openTender(id){if(activateTender(id))go(state.newTender?'requirements':'comparison');}
function hasCurrentAssessment(){return !state.newTender&&!state.stale;}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200)}
function go(next){if(next==='projects')next='tenders';if(!validViews.includes(next))return;view=next;const u=new URL(location);u.searchParams.set('view',next);if(next==='tenders')u.searchParams.delete('tender');else u.searchParams.set('tender',activeId);history.replaceState(null,'',u);render();window.scrollTo({top:0,behavior:'instant'})}
function foot(){return '<div class="page-foot"><span>Sample comparison · Prices include tax & delivery unless noted.</span><span>Made for a clearer decision. ✦</span></div>'}
function tabs(){return '';}
function tenderHead(){return `<div class="page-heading"><div><div class="eyebrow" style="font-size:8px;color:#ad98bb;margin-bottom:9px">${esc(state.brief.project)} <span> / </span> ${state.newTender?'NEW TENDER':'QL–024'}</div><h1>${esc(state.brief.name)}</h1><p>${esc(state.brief.quantity)} units <span style="padding:0 7px">·</span> ${esc(state.brief.location)} <span style="padding:0 7px">·</span> Budget ${money(state.brief.min)}–${money(state.brief.max)}</p></div><div class="heading-actions"><button class="button small" data-go="requirements">Edit brief</button><button class="button primary small" data-go="quotations">+ Add quotations</button></div></div>${tabs()}`}
function projectPage(){return `<div class="page-heading"><div><span class="eyebrow home-eyebrow">YOUR PURCHASES, WITH PERSPECTIVE</span><h1>My tenders<span class="title-dot">.</span></h1><p>Every tender has its own brief, quotations, comparison, and conversations.</p></div><button class="button small primary" data-action="new">+ New tender</button></div><div class="home-editorial"><div><span class="chip gold">ONE PLACE. A CLEAR NEXT STEP.</span><h2>Big plans start with<br>a well-chosen partner.</h2><p>Open a tender to pick up where you left off.</p></div><div class="home-count"><strong>${String(tenders.length).padStart(2,'0')}</strong><span>${tenders.length===1?'tender':'tenders'} in your workspace</span></div></div><div class="section-row home-list-title"><h2>All tenders</h2><span>${tenders.filter(t=>!t.newTender).length} sample comparison · ${tenders.filter(t=>t.newTender).length} personal drafts</span></div><div class="project-grid">${tenders.map(t=>`<a class="project-card" href="?tender=${encodeURIComponent(t.id)}&view=${t.newTender?'requirements':'comparison'}" data-open-tender="${esc(t.id)}"><div class="section-row"><span class="supplier-icon ${t.newTender?'peach':'purple'}">${t.newTender?'N':'TS'}</span><span class="chip ${t.newTender?'neutral':t.stale?'amber':'violet'}">${t.newTender?'Draft':t.stale?'Brief updated':'Ready to review'}</span></div><span class="tender-parent">${esc(t.brief.project)}</span><h2>${esc(t.brief.name)}</h2><p>${t.newTender?'Build your brief and bring your supplier offers together.':'Five offers reviewed. Three shortlisted. One clearer decision.'}</p><div class="project-meta"><span>${t.brief.max?money(t.brief.max)+' ceiling':'Budget to set'}</span><span>${(t.newTender?0:5)+t.custom.length} quotations</span><span class="card-arrow">↗</span></div></a>`).join('')}<button class="project-card empty" data-action="new"><span class="empty-plus">+</span><h2>What are you buying next?</h2><p>Create a separate tender workspace.</p></button></div><div class="page-foot"><span>Your tender data stays separate. Local design preview.</span><a href="index.html">Company website ↗</a></div>`}
function requirements(){const b=state.brief;return `${tenderHead()}<div class="form-grid"><form class="panel" id="brief-form"><h2>The details make the difference.</h2><div class="field-row"><div class="field"><label for="brief-name">Tender name</label><input id="brief-name" name="name" value="${esc(b.name)}" required></div><div class="field"><label for="brief-project">Event / organisation</label><input id="brief-project" name="project" value="${esc(b.project)}" required></div></div><div class="field"><label for="brief-description">What are you looking for?</label><textarea id="brief-description" name="description" required>${esc(b.description)}</textarea></div><div class="field-row"><div class="field"><label for="brief-quantity">Quantity</label><input id="brief-quantity" name="quantity" type="number" min="1" value="${b.quantity}" required></div><div class="field"><label for="brief-date">Required by</label><input id="brief-date" name="date" type="date" value="${esc(b.date)}" required></div></div><div class="field"><label for="brief-location">Delivery / service location</label><input id="brief-location" name="location" value="${esc(b.location)}" required></div><div class="field-row"><div class="field"><label for="brief-min">Expected range · From (₹)</label><input id="brief-min" name="min" type="number" min="0" value="${b.min}" required></div><div class="field"><label for="brief-max">Maximum budget (₹)</label><input id="brief-max" name="max" type="number" min="0" value="${b.max}" required></div></div><div class="field"><label for="brief-must">Must-have requirements</label><textarea id="brief-must" name="must" required>${esc(b.must)}</textarea></div><div class="field"><label for="brief-addons">Nice-to-haves / add-ons</label><textarea id="brief-addons" name="addons">${esc(b.addons)}</textarea></div><div class="field"><label for="brief-flex">Where can you compromise?</label><textarea id="brief-flex" name="flex">${esc(b.flex)}</textarea></div><div class="field"><label for="brief-priority">What matters most?</label><select id="brief-priority" name="priority">${['Balanced: quality, cost and delivery','Lowest complete cost','Highest quality','Earliest delivery'].map(v=>`<option ${v===b.priority?'selected':''}>${v}</option>`).join('')}</select></div><div id="brief-error" class="error-message" role="alert"></div><div class="form-footer"><span class="saved-note">Saved in this browser when you continue.</span><button class="button primary small" type="submit">Save & add quotations →</button></div></form><aside class="panel form-aside"><span class="eyebrow">A STRONGER BRIEF</span><h3>Be clear about<br>what can't change.</h3><p>The most useful comparison starts with your non-negotiables.</p><ul><li>Separate essentials from extras.</li><li>Set a complete budget, including taxes.</li><li>Be specific about dates.</li><li>Give compromises a limit.</li></ul><p style="margin-top:22px">Your internal budget stays in your workspace.</p></aside></div>`}
function quotations(){const offers=state.newTender?[]:sampleOffers;return `${tenderHead()}<div class="dropzone" id="dropzone"><div class="upload-symbol">↥</div><h2>Every quotation, in one place.</h2><p>Drop supplier PDFs here, or choose files from your device.</p><input id="files" type="file" accept="application/pdf,.pdf" multiple hidden><button class="button small" data-action="upload">+ Choose PDFs</button><p style="font-size:9px;margin:12px 0 0">Prototype: files stay in your browser. AI extraction is not connected.</p></div><div class="quote-list"><div class="section-row"><h2>Supplier quotations</h2><span>${offers.length+state.custom.length} documents</span></div>${offers.map(o=>`<div class="quote-row"><span class="supplier-icon ${o.colour}">${o.initial}</span><div class="quote-info"><strong>${o.name}</strong><small>${o.file} · ${o.contact}</small></div><span class="quote-status">Sample data ready</span><button class="button" data-evidence="${o.id}">View details ↗</button></div>`).join('')}${state.custom.map((o,i)=>`<div class="quote-row"><span class="supplier-icon purple">PDF</span><div class="quote-info"><strong>${esc(o.supplier||o.file)}</strong><small>${esc(o.file)} · ${o.bytes?(o.bytes/1024).toFixed(0)+' KB':'PDF'} · Saved locally</small></div><span class="chip amber">${o.supplier?'Details added':'Needs review'}</span><button class="button" data-edit-upload="${i}">Add details</button><button class="button" data-open-upload="${i}">Open PDF ↗</button></div>`).join('')}</div><div class="quotations-actions">${state.newTender?'<button class="button small" data-action="manual-note">Review comparison options →</button>':'<button class="button primary small" data-action="analyse">Review sample analysis →</button>'}</div>`}
const rows=[['Mandatory specifications','180 GSM cotton','180 GSM cotton','200 GSM cotton',false],['Delivery deadline','8 Nov · 2 days early','9 Nov · 1 day early','6 Nov · 4 days early',false],['Advance payment','30%','40%','25%',false],['Printed sample','Included','₹800 optional','Included',false],['Packaging','Individual','Bulk · acceptable','Individual',false],['Tax & delivery','Included','Included','Included',true],['Complete base total','₹32,400','₹30,200','₹34,500',false]];
function comparison(){if(!hasCurrentAssessment())return `${tenderHead()}<div class="panel empty-state"><h2>${state.stale?"Your brief changed. Review the offers again.":"Your comparison starts with the offers."}</h2><p>Upload quotations and add supplier details first.</p><p style="font-size:11px;margin:15px 0 25px">This design prototype includes a complete sample comparison. Live AI evaluation is not connected.</p><button class="button small primary" data-go="quotations">Back to quotations →</button></div>`;return `${tenderHead()}<div class="insight-banner"><span class="insight-spark">✦</span><div><strong>Five offers. Three strong contenders.</strong><p>Studio Merch offers the best overall fit. Campus Supply could be competitive if it improves delivery.</p></div><button data-go="evaluation">Open evaluation log ↗</button></div><div class="decision-summary"><span class="decision-number">01</span><div><span class="eyebrow">THE RECOMMENDATION</span><h2>Start with Studio Merch.</h2><p>It meets every essential, includes the printed sample and individual packaging, and leaves ₹2,600 inside your budget. Print & Co. is ₹2,200 cheaper at base price; adding its ₹800 sample narrows that difference to ₹1,400. Threadworks is the better option if earlier delivery matters more.</p><span class="summary-next">NEXT MOVE <b>Request ₹31,000 with the full scope retained.</b></span></div></div><div class="section-row"><h2>Your top three</h2><span>Sample shortlist · Balanced priorities</span></div><div class="shortlist">${sampleOffers.slice(0,3).map(o=>`<article class="offer-card ${o.rank===1?'best':''}"><div class="offer-ribbon"><span>${o.rank===1?'✦ ':''}${o.label}</span><span>0${o.rank}</span></div><div class="offer-body"><div class="offer-company"><span class="supplier-icon ${o.colour}">${o.initial}</span><div><h3>${o.name}</h3><p>Delhi NCR · Sample supplier</p></div></div><div class="offer-total">${money(o.total)}</div><p class="offer-sub">100 units · All-inclusive base offer</p><div class="offer-facts"><div><span>Delivery</span><b>${o.date}</b></div><div><span>Advance</span><b>${o.advance}</b></div><div><span>Essentials</span><b class="green-text">✓ All met</b></div></div><div class="offer-summary"><span>WHY THIS OFFER</span><p>${esc(o.note)}</p><button class="source-link" data-evidence="${o.id}">View source details ↗</button></div><button class="button" data-draft="${o.id}">Review negotiation draft <span>↗</span></button></div></article>`).join('')}</div><section class="compare-block"><div class="section-row"><h2>The details, side by side.</h2><label class="switch-label"><input type="checkbox" id="differences"> Differences only</label></div><div class="table-wrap"><table class="comparison-table"><thead><tr><th scope="col">What matters to you</th><th scope="col">Studio Merch</th><th scope="col">Print & Co.</th><th scope="col">Threadworks</th></tr></thead><tbody>${rows.map(r=>`<tr ${r[4]?'data-same="true"':''}><td>${r[0]}</td>${r.slice(1,4).map(v=>`<td>${v==='Included'?'<span class="tiny-check">✓</span> ':''}${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="table-note"><span>ⓘ</span> Sample data. Optional add-ons remain separate from complete base totals.</div></section><div class="potential"><span class="supplier-icon mint">C</span><div><h3>Outside the shortlist. Still worth a conversation.</h3><p>Campus Supply · ₹28,800 · Saves ₹3,600 against Studio Merch, but delivery misses your deadline by 2 days.</p></div><button class="button" data-draft="campus">Ask for revised delivery ↗</button></div>${foot()}`}
function evaluation(){if(!hasCurrentAssessment())return `${tenderHead()}<div class="panel empty-state"><h2>No current evaluation for this tender.</h2><p>Evidence, criteria checks, and decision summaries will appear after this tender is evaluated.</p><button class="button small" data-go="quotations" style="margin-top:20px">Review quotations →</button></div>`;const entries=[['Brief baseline','Requirements locked for this sample','100 T-shirts · minimum 180 GSM cotton · delivery by 10 November · advance ≤40% · maximum total ₹35,000. Printed sample and individual packaging are preferences.','Source: sample buyer brief · Revision 1'],['Offer review','Five supplier records reviewed','Material, unit count, base total, delivery date, payment terms, sample charges, and packaging were recorded for each offer. Tax and delivery are included in these sample base totals.','Source: five illustrative quotation records'],['Eligibility','Three meet the mandatory conditions','Studio Merch, Print & Co. and Threadworks meet the essentials. Campus Supply proposes 12 November delivery. QuickPrint proposes 160 GSM blended fabric, 11 November delivery, and 100% advance.','Rule: mandatory failures are not offset by a lower price'],['Cost normalisation','Optional costs stay visible','Studio Merch: ₹32,400. Print & Co.: ₹30,200 base or ₹31,000 with its optional sample. Threadworks: ₹34,500. These totals describe comparable base scope; packaging differs.','Calculation: ₹30,200 + ₹800 = ₹31,000'],['Decision summary','Studio Merch is the balanced recommendation','The recommendation favours meeting the brief and including both preferences. Print & Co. is better for minimising cost; Threadworks is better for earliest delivery. No verified supplier performance data is available.','Basis: balanced priorities · not an invented confidence score'],['Opportunity','One excluded offer may become competitive','Campus Supply is ₹3,600 below Studio Merch. Its other stated essentials match, so request a delivery revision before reconsidering it. QuickPrint requires several material changes.','Action: draft a targeted delivery clarification'],['Next action','Buyer reviews the recommendation and drafts','Request better commercial terms from shortlisted suppliers. Confirm all revised terms in writing. New replies or brief changes require a new evaluation.','Uncertainty: actual stock, execution quality and supplier reliability are not verified']];return `${tenderHead()}<div class="log-heading"><div><span class="eyebrow">EVIDENCE → CRITERIA → OUTCOME</span><h2>How the recommendation was reached.</h2><p>An inspectable evaluation summary: inputs, checks, calculations, trade-offs, and next actions.</p></div><span class="chip gold">Sample evaluation · V1</span></div><div class="evaluation-log">${entries.map((e,i)=>`<article class="log-entry"><div class="log-index">${String(i+1).padStart(2,'0')}</div><div><span class="log-stage">${e[0]}</span><h3>${e[1]}</h3><p>${e[2]}</p><div class="log-source">${e[3]}</div></div></article>`).join('')}</div><div class="log-disclosure">This is a structured explanation of the sample assessment, not private internal model reasoning or a live agent trace.</div><button class="button small primary" data-go="comparison">Back to comparison →</button>`}
function drafts(){if(!hasCurrentAssessment())return `${tenderHead()}<div class="panel empty-state"><span class="empty-plus">✉</span><h2>Your supplier conversations start here.</h2><p>${state.stale?'Your brief changed. Existing sample drafts need reassessment.':'Drafts for this tender will appear after its offers have been reviewed.'}</p><button class="button small primary" data-go="quotations" style="margin-top:25px">Go to this tender’s quotations →</button></div>`;let offers=sampleOffers.slice(0,4),o=offers.find(x=>x.id===selectedDraft)||offers[0];const d=state.drafts[o.id]||{email:o.email,subject:'Revised quotation request — College fest merchandise',body:`Hi ${o.contact},\n\n${o.draft}\n\nRegards,\nTechSpace team`};return `${tenderHead()}<div class="section-row"><div><h2>The right follow-up, already started.</h2><p style="margin-top:7px">Sample negotiation drafts · Review every detail before sending.</p></div><span class="chip violet">4 drafts</span></div><div class="draft-layout"><div class="draft-list">${offers.map(x=>`<button class="draft-select ${o.id===x.id?'active':''}" data-draft="${x.id}"><strong>${x.name}</strong><span>${x.id==='campus'?'Potential · Delivery revision':x.id==='print'?'Shortlisted · Include sample':'Shortlisted · Negotiate price'}</span></button>`).join('')}</div><form class="panel email-panel" id="draft-form"><div class="email-meta"><span>To</span><input aria-label="Recipient email" name="email" type="email" required value="${esc(d.email)}"></div><div class="email-meta"><span>Subject</span><input aria-label="Email subject" name="subject" required value="${esc(d.subject)}"></div><textarea class="email-body" name="body" aria-label="Email draft" required>${esc(d.body)}</textarea><div class="email-reason"><strong>Why this draft:</strong> ${esc(o.note)}</div><div class="form-footer"><button class="button small" type="submit">Save draft</button><div style="display:flex;gap:10px"><button type="button" class="button small" data-action="copy-draft">Copy</button><button type="button" class="button small primary" data-action="email-connect">Connect email ↗</button></div></div></form></div><div class="page-foot"><span>Draft only · No emails are sent from this design preview.</span><span>Your requirements stay in control.</span></div>`}
function render(){document.title=(view==='tenders'?'My tenders':state.brief.name)+' — QuoteLens';$('#crumb').textContent=view==='tenders'?'My tenders':state.brief.name;const inside=view!=='tenders';$('.sidebar').innerHTML=`<a class="brand" href="index.html"><span class="brand-mark">q</span>quotelens</a>${inside?`<button class="back-tenders" data-go="tenders">← All tenders</button><div class="active-tender"><span class="tender-emblem">${state.newTender?'N':'TS'}</span><span class="eyebrow">TENDER WORKSPACE</span><strong>${esc(state.brief.name)}</strong><small>${esc(state.brief.project)}</small></div><nav class="app-nav" aria-label="This tender"><p class="nav-label">INSIDE THIS TENDER</p>${[['requirements','▤','Tender details'],['quotations','▧','Quotations'],['comparison','◫','Comparison'],['evaluation','≡','Agent activity'],['drafts','✉','Email drafts']].map(([id,icon,label])=>`<button data-go="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span class="nav-symbol">${icon}</span>${label}</button>`).join('')}</nav>`:`<div class="org-switch"><span class="org-icon">TS</span><div><strong>Personal workspace</strong><small>All your tender workspaces</small></div></div><nav class="app-nav" aria-label="Workspace"><p class="nav-label">YOUR WORKSPACE</p><button class="active" data-go="tenders" aria-current="page"><span class="nav-symbol">▤</span>My tenders <span class="nav-count">${tenders.length}</span></button></nav>`}<div class="sidebar-bottom"><div class="prototype-note"><span class="mini-sun">✳</span><strong>Clarity in every detail.</strong>${inside?'Files and drafts belong only to this tender.':'A fresh workspace for each purchase.'}</div><div class="account"><span class="avatar">MG</span><div><strong>Madhav</strong><small>Design preview · Local data</small></div></div></div>`;$('#main').innerHTML=view==='tenders'?projectPage():view==='requirements'?requirements():view==='quotations'?quotations():view==='comparison'?comparison():view==='evaluation'?evaluation():drafts();bindView();}
function bindView(){if($('#brief-form'))$('#brief-form').addEventListener('submit',e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.currentTarget));if(Number(v.min)>Number(v.max)){$('#brief-error').textContent='Your maximum budget must be at least the lower end of your range.';return}['min','max','quantity'].forEach(k=>v[k]=Number(v[k]));const updated={...state.brief,...v};if(!state.newTender&&JSON.stringify(updated)!==JSON.stringify(state.brief))state.stale=true;state.brief=updated;(state.activity??=[]).push({at:new Date().toISOString(),level:'INFO',event:'brief.saved',message:'Saved the brief and agent preferences; any previous assessment is marked outdated.'});if(persist())toast('Tender details saved in this browser.');go('quotations')});if($('#differences'))$('#differences').addEventListener('change',e=>document.querySelectorAll('[data-same]').forEach(row=>row.hidden=e.target.checked));if($('#draft-form'))$('#draft-form').addEventListener('submit',e=>{e.preventDefault();state.drafts[selectedDraft]=Object.fromEntries(new FormData(e.currentTarget));if(persist())toast('Draft saved. No email sent.')});if($('#files'))$('#files').addEventListener('change',e=>addFiles([...e.target.files]));if($('#dropzone')){const z=$('#dropzone');z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('dragover')});z.addEventListener('dragleave',()=>z.classList.remove('dragover'));z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('dragover');addFiles([...e.dataTransfer.files])})}}
function modal(title,content){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close-button" data-action="close" aria-label="Close dialog">×</button></div>${content}</section></div>`;$('#modal-root .close-button').focus()}
function closeModal(){$('#modal-root').innerHTML='';lastFocus?.focus()}
function openEvidence(id){const o=sampleOffers.find(x=>x.id===id);modal(o.name,`<span class="chip violet">Illustrative quotation record</span><div class="source-detail"><strong>${o.file}</strong><p>${o.material} · 100 units<br>Complete base total: ${money(o.total)}<br>Delivery: ${o.date} 2026<br>Advance: ${o.advance}<br>Sample: ${o.sample}<br>Packaging: ${o.pack}</p></div><p>${o.note}</p><p class="small-muted">${o.contact} · ${o.email}<br>Sample data supplied for design review; not extracted from a real supplier PDF.</p><button class="button small" data-action="close">Back to quotations</button>`)}
async function db(){return new Promise((resolve,reject)=>{const req=indexedDB.open('quotelens-files-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function putFile(key,file){const d=await db();try{await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}finally{d.close()}}
async function getFile(key){const d=await db();try{return await new Promise((resolve,reject)=>{const r=d.transaction('files').objectStore('files').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}finally{d.close()}}
async function addFiles(files){const owner=state;let n=0;for(const file of files){if(!/\.pdf$/i.test(file.name)){toast('Please choose PDF files for supplier quotations.');continue}if(file.size>25*1024*1024){toast('Choose a PDF smaller than 25 MB for this preview.');continue}const id=crypto.randomUUID();try{await putFile(id,file);owner.custom.push({id,file:file.name,bytes:file.size,supplier:'',email:'',total:''});(owner.activity??=[]).push({at:new Date().toISOString(),level:'INFO',event:'quotation.saved',message:'Stored a supplier PDF locally. Extraction is not connected.'});n++}catch{toast('This browser could not save the PDF. Try another browser or a smaller file.')}}if(n){const ok=persist();render();if(ok)toast(`${n} PDF${n>1?'s':''} saved locally. Add supplier details to continue.`)}}
function editUpload(index){const f=state.custom[index];modal('Add quotation details',`<form id="upload-form"><p>Review the PDF and enter these details. Automatic extraction will be connected in the working app.</p><div class="field"><label for="up-name">Supplier name</label><input id="up-name" name="supplier" value="${esc(f.supplier)}" required></div><div class="field"><label for="up-contact">Contact name</label><input id="up-contact" name="contact" value="${esc(f.contact||'')}"></div><div class="field"><label for="up-email">Email</label><input id="up-email" name="email" type="email" value="${esc(f.email)}"></div><div class="field"><label for="up-total">Quoted total (₹)</label><input id="up-total" name="total" type="number" min="0" value="${esc(f.total)}"></div><button class="button small primary" type="submit">Save details</button></form>`);$('#upload-form').addEventListener('submit',e=>{e.preventDefault();Object.assign(f,Object.fromEntries(new FormData(e.currentTarget)));const ok=persist();closeModal();render();if(ok)toast('Quotation details saved.')})}
function newTender(){modal('A new tender. Its own workspace.',`<form id="new-form"><div class="field"><label for="new-title">Tender name</label><input id="new-title" name="name" placeholder="e.g. College fest merchandise" required></div><div class="field"><label for="new-project">Event / organisation</label><input id="new-project" name="project" placeholder="e.g. TechSpace Fest 2026" required></div><p>Your brief, PDFs, supplier contacts, comparisons, and drafts will live together in this tender.</p><button class="button small primary" type="submit">Create workspace →</button></form>`);$('#new-form').addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));createTender(f.name,f.project);closeModal();go('requirements')})}
function analyse(){modal('Following the details.',`<span class="chip violet">Sample workflow preview</span><p>Showing the analysis sequence using the five prepared sample quotations.</p><div class="progress-track"><div class="progress-fill" id="analysis-progress"></div></div><div class="progress-steps"><span>① Understand the requirements</span><span>② Review every supplier offer</span><span>③ Compare essentials, cost & trade-offs</span><span>④ Shortlist three & prepare follow-ups</span></div><p class="small-muted">No live model is running in this prototype.</p>`);let step=0;const timer=setInterval(()=>{if(!$('#analysis-progress')){clearInterval(timer);return}step++;$('#analysis-progress').style.width=step*25+'%';document.querySelectorAll('.progress-steps span').forEach((el,i)=>el.classList.toggle('complete',i<step));if(step===4){clearInterval(timer);setTimeout(()=>{if($('#analysis-progress')){closeModal();go('comparison')}},350)}},450)}
document.addEventListener('click',async e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.openTender){e.preventDefault();openTender(target.dataset.openTender);return}if(target.dataset.go){e.preventDefault();go(target.dataset.go);return}if(target.dataset.draft){selectedDraft=target.dataset.draft;go('drafts');return}if(target.dataset.evidence){openEvidence(target.dataset.evidence);return}if(target.dataset.editUpload!==undefined){editUpload(Number(target.dataset.editUpload));return}if(target.dataset.openUpload!==undefined){try{const f=await getFile(state.custom[Number(target.dataset.openUpload)].id);if(!f){toast('The saved PDF is unavailable in this browser.');return}const u=URL.createObjectURL(f);const a=document.createElement('a');a.href=u;a.download=f.name||'quotation.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}catch{toast('Could not open the locally saved PDF.')}return}switch(target.dataset.action){case 'new':newTender();break;case 'close':closeModal();break;case 'upload':$('#files').click();break;case 'analyse':if(state.stale)toast('The sample assessment is out of date. Live re-evaluation is not connected.');else analyse();break;case 'analysis-info':modal('Why these three?',`<div class="source-detail"><strong>Studio Merch · Best overall fit</strong><p>Meets all essential requirements, includes the sample and individual packaging, and stays within the budget.</p></div><div class="source-detail"><strong>Print & Co. · Best base price</strong><p>Meets essentials at ₹30,200. Printed sample costs an extra ₹800; bulk packaging is an allowed compromise.</p></div><div class="source-detail"><strong>Threadworks · Fastest delivery</strong><p>Delivers earliest, with 200 GSM cotton and a lower advance. Highest of the three prices, but still within budget.</p></div><p>Campus Supply misses delivery. QuickPrint fails material, delivery, and payment conditions. This is a prepared sample assessment, not a live ranking.</p>`);break;case 'sample':closeModal();openTender('fest-2026');break;case 'manual-note':modal('The next step: evaluate the offers.',`<p>Your uploaded PDFs and supplier details are saved locally. Live extraction and AI comparison are not connected in this design prototype.</p><p>You can explore the full top-three comparison and negotiation experience with the prepared sample.</p><button class="button small primary" data-action="sample">Explore sample comparison →</button>`);break;case 'email-connect':modal('Your email, connected to the tender.',`<span class="chip violet">Connection preview</span><p>In the working product, connect Gmail here, review the recipient and attachments, and send your approved message. Supplier replies return to this tender.</p><p>This design preview does not connect an account or send messages. You can save or copy your draft.</p><button class="button small" data-action="close">Back to my draft</button>`);break;case 'copy-draft':try{await navigator.clipboard.writeText($('#draft-form textarea').value);toast('Draft copied.')}catch{toast('Select the draft text and copy it manually.')}break;}});
document.addEventListener('keydown',e=>{const modalEl=$('#modal-root .modal');if(!modalEl)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...modalEl.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('popstate',()=>{view=new URLSearchParams(location.search).get('view')||'tenders';if(!validViews.includes(view))view='tenders';const id=new URLSearchParams(location.search).get('tender');if(id)activateTender(id);render()});
render();
